) $cs;" ); update_option( 'dvb_db', DVB_DB, false ); } function dvb_now() { return current_time( 'mysql', true ); } function dvb_iso( $mysql ) { return $mysql ? gmdate( 'c', strtotime( $mysql . ' UTC' ) ) : ''; } function dvb_text( $v, $max = 160 ) { return mb_substr( sanitize_text_field( (string) $v ), 0, $max ); } function dvb_ic( $v ) { $v = strtoupper( preg_replace( '/[^0-9A-Za-z]/', '', (string) $v ) ); if ( preg_match( '/^\d{11}$/', $v ) ) { $v = '0' . $v; } return mb_substr( $v, 0, 24 ); } function dvb_phone( $v ) { $v = trim( (string) $v ); $plus = str_starts_with( $v, '+' ); $d = preg_replace( '/\D/', '', $v ); if ( ! $plus && preg_match( '/^1\d{8,9}$/', $d ) ) { $d = '0' . $d; } return mb_substr( ( $plus ? '+' : '' ) . $d, 0, 40 ); } function dvb_email( $v ) { $v = sanitize_email( (string) $v ); return is_email( $v ) ? mb_substr( $v, 0, 160 ) : ''; } function dvb_qty( $v ) { $n = (int) $v; return $n >= 1 && $n <= 99 ? $n : 1; } function dvb_rev() { return (int) get_option( 'dvb_rev', 0 ); } function dvb_bump() { $r = dvb_rev() + 1; update_option( 'dvb_rev', $r, false ); return $r; } function dvb_client_ip() { return preg_replace( '/[^0-9a-fA-F:.]/', '', (string) ( $_SERVER['REMOTE_ADDR'] ?? '' ) ); } function dvb_settings() { $s = get_option( 'dvb_settings', array() ); $s = is_array( $s ) ? $s : array(); return array_merge( array( 'title' => 'Grand Deepavali Celebration Ampang', 'subtitle' => 'Resit Pungutan Bantuan Deepavali', 'formOpen' => true, 'paper' => 'roll', 'width' => 40, 'footer' => 'Sila simpan resit ini. Please keep this receipt.', 'maxPerForm' => 100, ), $s ); } function dvb_receipt_no( $id ) { return 'B' . str_pad( (string) $id, 4, '0', STR_PAD_LEFT ); } function dvb_users() { $u = get_option( 'dvb_users', array() ); return is_array( $u ) ? $u : array(); } function dvb_sig( $exp, $uid ) { $u = dvb_users()[ $uid ] ?? null; return $u ? hash_hmac( 'sha256', $exp . '|' . $uid . '|' . $u['hash'], wp_salt( 'auth' ) ) : ''; } function dvb_session_user() { $c = explode( '.', (string) ( $_COOKIE[ DVB_COOKIE ] ?? '' ) ); if ( 3 !== count( $c ) || ! ctype_digit( $c[0] ) || (int) $c[0] <= time() ) { return null; } $u = dvb_users()[ $c[1] ] ?? null; $sig = dvb_sig( $c[0], $c[1] ); return ( $u && '' !== $sig && hash_equals( $sig, $c[2] ) ) ? array( 'id' => $c[1], 'name' => $u['name'], 'admin' => ! empty( $u['admin'] ) ) : null; } function dvb_is_wp_admin() { return current_user_can( 'manage_options' ); } function dvb_can() { return dvb_is_wp_admin() || null !== dvb_session_user(); } function dvb_is_admin() { if ( dvb_is_wp_admin() ) { return true; } $u = dvb_session_user(); return $u && $u['admin']; } function dvb_me() { $u = dvb_session_user(); if ( $u ) { return $u['name']; } return is_user_logged_in() ? wp_get_current_user()->display_name : ''; } function dvb_set_session( $uid ) { $exp = (string) ( time() + DVB_TTL ); setcookie( DVB_COOKIE, $exp . '.' . $uid . '.' . dvb_sig( $exp, $uid ), array( 'expires' => (int) $exp, 'path' => '/', 'secure' => is_ssl(), 'httponly' => true, 'samesite' => 'Lax', ) ); } function dvb_set_user( $name, $code, $admin = false ) { $name = dvb_text( $name, 60 ); $code = trim( (string) $code ); if ( '' === $name || strlen( $code ) < 6 || strlen( $code ) > 64 ) { return new WP_Error( 'dvb_bad_code', 'A person needs a name and a code of 6 to 64 characters.', array( 'status' => 400 ) ); } $users = dvb_users(); foreach ( $users as $k => $u ) { if ( 0 !== strcasecmp( $u['name'], $name ) && wp_check_password( $code, $u['hash'] ) ) { return new WP_Error( 'dvb_dup_code', 'Someone else already uses that code. Pick another.', array( 'status' => 400 ) ); } } $id = ''; foreach ( $users as $k => $u ) { if ( 0 === strcasecmp( $u['name'], $name ) ) { $id = $k; } } $id = $id ?: 'u' . wp_rand( 100000, 999999 ); $users[ $id ] = array( 'name' => $name, 'hash' => wp_hash_password( $code ), 'admin' => (bool) $admin ); update_option( 'dvb_users', $users, false ); return $id; } function dvb_row_out( $r ) { return array( 'id' => (int) $r->id, 'ic' => $r->ic, 'name' => $r->name, 'phone' => $r->phone, 'email' => $r->email, 'qty' => (int) $r->qty, 'picName' => $r->pic_name, 'picPhone' => $r->pic_phone, 'picIc' => $r->pic_ic, 'notes' => $r->notes, 'status' => $r->status, 'receiptId' => (int) $r->receipt_id, 'collectedAt' => dvb_iso( $r->collected_at ), 'collectedBy' => $r->collected_by, 'batch' => $r->batch, 'updatedAt' => dvb_iso( $r->updated_at ), ); } function dvb_receipt_out( $r ) { return array( 'id' => (int) $r->id, 'no' => dvb_receipt_no( $r->id ), 'picName' => $r->pic_name, 'picPhone' => $r->pic_phone, 'picIc' => $r->pic_ic, 'qty' => (int) $r->qty, 'items' => json_decode( $r->items, true ) ?: array(), 'claimId' => (int) $r->claim_id, 'issuedBy' => $r->issued_by, 'createdAt' => dvb_iso( $r->created_at ), 'voidedAt' => dvb_iso( $r->voided_at ), 'voidedBy' => $r->voided_by, 'voidReason' => $r->void_reason, ); } function dvb_claim_out( $r ) { return array( 'id' => (int) $r->id, 'ref' => $r->ref, 'picName' => $r->pic_name, 'picPhone' => $r->pic_phone, 'picIc' => $r->pic_ic, 'items' => json_decode( $r->items, true ) ?: array(), 'status' => $r->status, 'receiptId' => (int) $r->receipt_id, 'note' => $r->note, 'createdAt' => dvb_iso( $r->created_at ), 'updatedAt' => dvb_iso( $r->updated_at ), ); } function dvb_state() { global $wpdb; $out = array( 'rev' => dvb_rev(), 'recipients' => array_map( 'dvb_row_out', $wpdb->get_results( 'SELECT * FROM ' . dvb_t( 'recipients' ) . ' ORDER BY id ASC' ) ), 'receipts' => array_map( 'dvb_receipt_out', $wpdb->get_results( 'SELECT * FROM ' . dvb_t( 'receipts' ) . ' ORDER BY id DESC' ) ), 'claims' => array_map( 'dvb_claim_out', $wpdb->get_results( 'SELECT * FROM ' . dvb_t( 'claims' ) . ' ORDER BY id DESC LIMIT 3000' ) ), 'settings' => dvb_settings(), 'now' => gmdate( 'c' ), ); if ( dvb_is_admin() ) { $out['users'] = array(); foreach ( dvb_users() as $id => $u ) { $out['users'][] = array( 'id' => $id, 'name' => $u['name'], 'admin' => ! empty( $u['admin'] ) ); } } return $out; } function dvb_import( array $rows, $batch ) { global $wpdb; $t = dvb_t( 'recipients' ); $now = dvb_now(); $by_ic = array(); $by_np = array(); foreach ( $wpdb->get_results( "SELECT id, ic, name, phone, status FROM $t" ) as $r ) { if ( '' !== $r->ic ) { $by_ic[ $r->ic ] = $r; } $by_np[ strtolower( $r->name ) . '|' . $r->phone ] = $r; } $res = array( 'added' => 0, 'updated' => 0, 'skipped' => 0, 'locked' => 0, 'problems' => array() ); foreach ( $rows as $i => $in ) { if ( ! is_array( $in ) ) { continue; } $rec = array( 'ic' => dvb_ic( $in['ic'] ?? '' ), 'name' => dvb_text( $in['name'] ?? '', 160 ), 'phone' => dvb_phone( $in['phone'] ?? '' ), 'email' => dvb_email( $in['email'] ?? '' ), 'qty' => dvb_qty( $in['qty'] ?? 1 ), ); foreach ( array( 'picName' => 'pic_name', 'picPhone' => 'pic_phone', 'picIc' => 'pic_ic', 'notes' => 'notes' ) as $k => $col ) { $v = $in[ $k ] ?? ''; if ( '' !== trim( (string) $v ) ) { $rec[ $col ] = 'pic_phone' === $col ? dvb_phone( $v ) : ( 'pic_ic' === $col ? dvb_ic( $v ) : dvb_text( $v, 'notes' === $col ? 500 : 120 ) ); } } $line = (int) ( $in['line'] ?? ( $i + 2 ) ); if ( '' === $rec['name'] ) { $res['skipped']++; $res['problems'][] = array( 'line' => $line, 'msg' => 'No name' ); continue; } $hit = '' !== $rec['ic'] ? ( $by_ic[ $rec['ic'] ] ?? null ) : ( $by_np[ strtolower( $rec['name'] ) . '|' . $rec['phone'] ] ?? null ); if ( $hit ) { if ( 'collected' === $hit->status ) { $res['locked']++; continue; } $rec['updated_at'] = $now; $wpdb->update( $t, $rec, array( 'id' => $hit->id ) ); $res['updated']++; continue; } $rec += array( 'pic_name' => '', 'pic_phone' => '', 'pic_ic' => '', 'notes' => '' ); $rec['batch'] = dvb_text( $batch, 60 ); $rec['status'] = 'pending'; $rec['created_at'] = $now; $rec['updated_at'] = $now; $wpdb->insert( $t, $rec ); $obj = (object) array( 'id' => $wpdb->insert_id, 'ic' => $rec['ic'], 'name' => $rec['name'], 'phone' => $rec['phone'], 'status' => 'pending' ); if ( '' !== $rec['ic'] ) { $by_ic[ $rec['ic'] ] = $obj; } $by_np[ strtolower( $rec['name'] ) . '|' . $rec['phone'] ] = $obj; $res['added']++; } dvb_bump(); return $res; } function dvb_collect( array $ids, array $pic, $claim_id, $who, $extra = 0, array $add = array() ) { global $wpdb; $t = dvb_t( 'recipients' ); if ( $add && $claim_id ) { $ids = array_merge( $ids, dvb_add_walkins( (int) $claim_id, $add ) ); } $ids = array_values( array_unique( array_filter( array_map( 'intval', $ids ) ) ) ); $extra = max( 0, min( 500, (int) $extra ) ); if ( ! $ids && ! $extra ) { return new WP_Error( 'dvb_none', 'Pick at least one name, or enter the number of boxes.', array( 'status' => 400 ) ); } if ( count( $ids ) > 200 ) { return new WP_Error( 'dvb_many', 'At most 200 names on one receipt.', array( 'status' => 400 ) ); } $pic = array( 'pic_name' => dvb_text( $pic['name'] ?? '', 120 ), 'pic_phone' => dvb_phone( $pic['phone'] ?? '' ), 'pic_ic' => dvb_ic( $pic['ic'] ?? '' ), ); if ( '' === $pic['pic_name'] ) { return new WP_Error( 'dvb_pic', 'Who is collecting? Enter the PIC name.', array( 'status' => 400 ) ); } $in = $ids ? implode( ',', $ids ) : '0'; $rows = $ids ? $wpdb->get_results( "SELECT * FROM $t WHERE id IN ($in)" ) : array(); if ( count( $rows ) !== count( $ids ) ) { return new WP_Error( 'dvb_gone', 'Some names are no longer on the list. Refresh and try again.', array( 'status' => 409 ) ); } $done = array_filter( $rows, fn( $r ) => 'pending' !== $r->status ); if ( $done ) { $names = implode( ', ', array_map( fn( $r ) => $r->name . ' (' . dvb_receipt_no( $r->receipt_id ) . ')', $done ) ); return new WP_Error( 'dvb_already', 'Already collected: ' . $names . '.', array( 'status' => 409 ) ); } $items = array(); $qty = 0; foreach ( $rows as $r ) { $items[] = array( 'id' => (int) $r->id, 'name' => $r->name, 'ic' => $r->ic, 'qty' => (int) $r->qty ); $qty += (int) $r->qty; } if ( $extra ) { $items[] = array( 'id' => 0, 'name' => 'Tanpa nama', 'ic' => '', 'qty' => $extra, 'extra' => 1 ); $qty += $extra; } $no